export type RequestInput={enrollment_ref:string;analog_transponders:number;digital_transponders:number;calibration_frames:number;whiteout_warning:boolean};export const score=(a:number,d:number,c:number,w:boolean)=>{const t=a+d,e=a*9+d*16+(w?c*7:0),x=c*50;return Math.min(e,x)+Math.max(e-x,0)*8+Math.trunc((t+5)/6)*5};export const calculate=(v:RequestInput)=>{const t=v.analog_transponders+v.digital_transponders,e=v.analog_transponders*9+v.digital_transponders*16+(v.whiteout_warning?v.calibration_frames*7:0),a=v.calibration_frames*50,r=Math.max(e-a,0);return {enrollment_ref:v.enrollment_ref,transponder_tally:t,tuning_effort:e,frame_allowance:a,commissioned_effort:Math.min(e,a),uncommissioned_effort:r,tuning_rounds:Math.trunc((t+5)/6),enrollment_rating:score(v.analog_transponders,v.digital_transponders,v.calibration_frames,v.whiteout_warning),enrollment_phase:r===0?'enrolled':v.whiteout_warning?'whiteout_hold':'routine_hold'}};export async function loadParley(){return {beacon_enrollment_rating:(a0:number,a1:number,a2:number,a3:boolean)=>BigInt(score(a0,a1,a2,a3))}}
