import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {z} from 'zod';import {calculate,type RequestInput} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const maxBodyBytes=16_384;const schema=z.object({enrollment_ref:z.string(),analog_transponders:z.number().int(),digital_transponders:z.number().int(),calibration_frames:z.number().int(),whiteout_warning:z.boolean()}).strict();
const response=(value:unknown,status=200,headers:Record<string,string>={})=>{if(Object.keys(headers).some(name=>['content-length','content-type','connection','transfer-encoding','x-content-type-options'].includes(name.toLowerCase())))return new Response(JSON.stringify({error:'invalid_response_headers',detail:'server-owned response header'}),{status:500,headers:{'content-type':'application/json'}});return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json',...headers}})};const error=(code:string,status:number,detail:string)=>response({error:code,detail},status);const zero=(v:RequestInput,state:string)=>({enrollment_ref:v.enrollment_ref,transponder_tally:0,tuning_effort:0,frame_allowance:0,commissioned_effort:0,uncommissioned_effort:0,tuning_rounds:0,enrollment_rating:0,enrollment_phase:state});const decide=(v:RequestInput,headers:Headers)=>{if((headers.get('x-rescue-pass')??'')!=="beacon-046")return response(zero(v,'authorization_required'),403,{"x-access-denial":"rescue_pass"});if([v.analog_transponders,v.digital_transponders,v.calibration_frames].some(item=>item<0))return response(zero(v,'invalid'),422,{'x-validation':'nonnegative'});if(v.calibration_frames===0&&v.analog_transponders+v.digital_transponders>0)return response(zero(v,'invalid'),422,{'x-validation':'calibration_frames'});const body=calculate(v);return response(body,201,{'location':`/api/v10/beacon-enrollments/${v.enrollment_ref}`,'retry-after':'4','x-enrollment-phase':String(body.enrollment_phase)});};
const app=new Hono();app.get('/status/beacon-enrollment-ready',()=>response({service:'Beacon Enrollment',ready:true}));app.post('/api/v10/beacon-enrollments',async context=>{const media=(context.req.header('content-type')??'').split(';',1)[0]!.trim().toLowerCase();if(media!=='application/json'&&!media.endsWith('+json'))return error('json_content_type_required',415,'expected application/json');const declared=context.req.header('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>maxBodyBytes))return error('body_too_large',413,'request body exceeds 16384 bytes');const raw=await context.req.arrayBuffer();if(raw.byteLength>maxBodyBytes)return error('body_too_large',413,'request body exceeds 16384 bytes');try{const parsed=schema.safeParse(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));if(!parsed.success)return error('invalid_json',400,parsed.error.message);return decide(parsed.data,context.req.raw.headers)}catch(caught){return error('invalid_json',400,String(caught))}});app.all('/api/*',context=>error('not_found',404,`no API route ${context.req.path}`));app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_046_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});
